//! A minigame's map pool by player count (docs/plans/active/
//! map-pool-fitness.md): which of the pool's maps a rotation may draw for
//! the players present, and how likely each is. Data, not code:
//!
//! - **Measurements**: each game's data/map_fitness.toml (`Fitness` per
//!   map: walkable area, sight, spawn points and spots), generated by the
//!   `map_fitness` tool (`--write`) from a sweep of the installs.
//! - **Rules**: each game's data/map_pool.toml, hand-written: `[[deny]]`
//!   and `[[allow]]` tables of map names (`*` matches any run of
//!   letters: `bhop_*`, `*_cp`) with their reason (`PoolRules`). Deny
//!   leaves a map out of an automatic pool (`MapPool::listed`, read by
//!   `auto::report` in place of a name pattern: a game with rules offers
//!   every installed map its rules don't deny); allow wins over deny and
//!   over the measurements' flags (a map the numbers can't judge).
//! - **The rule's numbers**: `FitSettings`, chimera/sim/data/map_fit.toml
//!   (`DATA`) tuned by a definition's `map_fit` (on by default with
//!   `rotation = "random"`).
//!
//! Both kinds of file are registered per game (`MapPoolAppExt`) into one
//! resource, `MapPool`. At a map change the host counts the characters
//! present, humans and bots (`present`), and judges each map of the pool
//! (`MapPool::judge`): out when its rules deny it, its measurements say
//! it didn't load or can't be judged (no walkable region, no spawn point,
//! an area over `look_area_m2`, `look_off_share` of its spots off the
//! map), or its wander time at that count is over `target_s` (unless it
//! is small: `small_m2`, or `chaos_s` at 4 players); else in at the
//! weight the settings' curve gives its wander time, a small map's
//! scaled by `small_scale`. A map without measurements is in at
//! `unknown_weight`, said once in the log (`draw_weights`). The rotation
//! (`rotation::MapHistory::next_weighted`) and the map vote
//! (`vote::candidates_weighted`) draw by these weights, the recently
//! played held back as before; the asset offer prefetches the maps let
//! in, likeliest first (`likeliest`).
//!
//! Known shortcuts: the count is the characters present at the change,
//! not those who will join; a game without measurements has every map at
//! `unknown_weight`; the wander model's own (players spread evenly,
//! walking blind).

use std::collections::BTreeMap;

use bevy::prelude::*;
use chimera_core::core::{Health, Intent, Npc};
use serde::Deserialize;

use super::{
    MinigameDef,
    def::{MapVoteParam, Rotation},
};

/// The built-in settings (chimera/sim/data/map_fit.toml).
pub const DATA: &str = include_str!("../../data/map_fit.toml");

/// The rule's numbers (`DATA`, a definition's `map_fit` over it).
#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FitSettings {
    /// The longest wander time (s) a map may take at the count.
    pub target_s: f32,
    /// A map of at most this walkable area (m2) is always in.
    pub small_m2: f32,
    /// A map whose wander time at 4 players is at most this (s) is always in.
    pub chaos_s: f32,
    /// Over this area (m2) the numbers can't judge a map: out unless allowed.
    pub look_area_m2: f32,
    /// This share or more of its spawn spots off the map: out unless allowed.
    pub look_off_share: f32,
    /// The wander model's run speed (m/s).
    pub speed_mps: f32,
    /// The longest sight counted (m).
    pub sight_cap_m: f32,
    /// The weight by wander time: `[s, weight]` points, straight between,
    /// flat beyond the ends.
    pub weights: Vec<[f32; 2]>,
    /// A small map's weight is this share of the curve's.
    pub small_scale: f32,
    /// A map without measurements: in at this weight.
    pub unknown_weight: f32,
}

impl FitSettings {
    /// `DATA` with `t`'s keys in place.
    pub fn with(t: &toml::Table) -> Result<Self, String> {
        let mut base: toml::Table = toml::from_str(DATA).map_err(|e| e.to_string())?;
        for (k, v) in t {
            base.insert(k.clone(), v.clone());
        }
        let s: Self = toml::Value::Table(base).try_into().map_err(|e: toml::de::Error| e.to_string())?;
        if s.weights.is_empty() || s.weights.windows(2).any(|w| w[1][0] <= w[0][0]) {
            return Err("weights: at least one point, seconds rising".into());
        }
        if s.weights.iter().any(|p| p[1] < 0.0) || s.small_scale < 0.0 || s.unknown_weight < 0.0 {
            return Err("weights can't be negative".into());
        }
        if s.target_s <= 0.0 || s.speed_mps <= 0.0 || s.sight_cap_m <= 0.0 {
            return Err("target_s, speed_mps and sight_cap_m must be more than 0".into());
        }
        Ok(s)
    }

    /// The built-in settings.
    pub fn shipped() -> Self {
        Self::with(&toml::Table::new()).expect("chimera/sim/data/map_fit.toml")
    }

    /// `def`'s settings: None when off (`map_fit = false`, or absent with
    /// the rotation in turn).
    pub fn of(def: &MinigameDef) -> Result<Option<Self>, String> {
        match &def.map_fit {
            None if def.rotation == Rotation::Random => Ok(Some(Self::shipped())),
            None | Some(MapVoteParam::On(false)) => Ok(None),
            Some(MapVoteParam::On(true)) => Ok(Some(Self::shipped())),
            Some(MapVoteParam::Tuned(t)) => Self::with(t).map(Some),
        }
    }

    /// The curve's weight at `wander` s.
    pub fn curve(&self, wander: f32) -> f32 {
        let pts = &self.weights;
        if wander <= pts[0][0] {
            return pts[0][1];
        }
        for w in pts.windows(2) {
            let ([a, wa], [b, wb]) = (w[0], w[1]);
            if wander <= b {
                return wa + (wb - wa) * (wander - a) / (b - a);
            }
        }
        pts[pts.len() - 1][1]
    }
}

fn yes() -> bool {
    true
}

/// One map's measurements (a game's data/map_fitness.toml).
#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Fitness {
    /// It loaded with a walkable region.
    #[serde(default = "yes")]
    pub loads: bool,
    /// The walkable area of its main region (m2).
    pub area_m2: f32,
    /// The mean sight from eye height (m).
    pub sight_m: f32,
    /// The area a walking player's spawn spots cover (m2), informational.
    #[serde(default)]
    pub spot_area_m2: f32,
    /// Its spawn points.
    pub spawns: u32,
    /// The spawn spots `random_hidden` picks from.
    pub spots: u32,
    /// Of those, off the map.
    #[serde(default)]
    pub spots_off: u32,
    /// Of those, where a standing player is stuck, informational.
    #[serde(default)]
    pub stuck: u32,
    /// The wander times the sweep worked out, by count, informational
    /// (`wander` works them out again with the settings' constants).
    #[serde(default)]
    pub wander_s: BTreeMap<String, f32>,
}

impl Fitness {
    /// The mean time (s) between a player's meetings with `players`
    /// present (one counts as two).
    pub fn wander(&self, players: usize, s: &FitSettings) -> f32 {
        let others = players.saturating_sub(1).max(1) as f32;
        let sight = self.sight_m.min(s.sight_cap_m);
        if sight <= 0.0 {
            return f32::INFINITY;
        }
        self.area_m2 / (others * 2.0 * sight * 4.0 / std::f32::consts::PI * s.speed_mps)
    }

    /// Small: always in, whatever the count.
    pub fn small(&self, s: &FitSettings) -> bool {
        self.area_m2 <= s.small_m2 || self.wander(4, s) <= s.chaos_s
    }

    /// Why it can't be played (None: it can): it didn't load, or has no
    /// walkable region or spawn point.
    pub fn broken(&self) -> Option<String> {
        if !self.loads || self.area_m2 <= 0.0 {
            Some("no walkable region from its spawn points".into())
        } else if self.spawns == 0 {
            Some("no spawn points".into())
        } else {
            None
        }
    }

    /// Why the numbers can't judge it (None: they can).
    pub fn look(&self, s: &FitSettings) -> Option<String> {
        if self.area_m2 > s.look_area_m2 {
            Some(format!("area {:.0} m2 over {:.0} (a leak or open terrain)", self.area_m2, s.look_area_m2))
        } else if self.spots > 0 && self.spots_off as f32 / self.spots as f32 >= s.look_off_share {
            Some(format!("{} of {} spawn spots off the map", self.spots_off, self.spots))
        } else {
            None
        }
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct FitnessDoc {
    /// The sweep's run speed (informational: `FitSettings::speed_mps`
    /// counts).
    #[serde(default)]
    #[allow(dead_code)]
    speed_mps: Option<f32>,
    #[serde(default)]
    maps: BTreeMap<String, Fitness>,
}

/// A game's data/map_fitness.toml read: each map's measurements by
/// name (lower case).
pub fn parse_fitness(text: &str) -> Result<BTreeMap<String, Fitness>, String> {
    let doc: FitnessDoc = toml::from_str(text).map_err(|e| e.to_string())?;
    Ok(doc.maps.into_iter().map(|(k, v)| (k.to_ascii_lowercase(), v)).collect())
}

/// Whether map name `name` matches `pattern` (`*`: any run of
/// characters), case-insensitive.
pub fn matches(pattern: &str, name: &str) -> bool {
    let (p, n) = (pattern.to_ascii_lowercase(), name.to_ascii_lowercase());
    let parts: Vec<&str> = p.split('*').collect();
    if parts.len() == 1 {
        return p == n;
    }
    let (first, last) = (parts[0], parts[parts.len() - 1]);
    if !n.starts_with(first) || n.len() < first.len() + last.len() || !n.ends_with(last) {
        return false;
    }
    let mut at = first.len();
    let end = n.len() - last.len();
    for mid in &parts[1..parts.len() - 1] {
        match n[at..end].find(mid) {
            Some(i) => at += i + mid.len(),
            None => return false,
        }
    }
    true
}

/// A game's pool rules (data/map_pool.toml): patterns with their reasons.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct PoolRules {
    pub deny: Vec<(String, String)>,
    pub allow: Vec<(String, String)>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RulesDoc {
    #[serde(default)]
    deny: Vec<RuleDoc>,
    #[serde(default)]
    allow: Vec<RuleDoc>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RuleDoc {
    maps: Vec<String>,
    reason: String,
}

impl PoolRules {
    /// A game's data/map_pool.toml read (`[[deny]]`, `[[allow]]`: `maps`
    /// and `reason`).
    pub fn parse(text: &str) -> Result<Self, String> {
        let doc: RulesDoc = toml::from_str(text).map_err(|e| e.to_string())?;
        let flat = |v: Vec<RuleDoc>| {
            v.into_iter()
                .flat_map(|r| r.maps.into_iter().map(move |m| (m, r.reason.clone())))
                .collect::<Vec<_>>()
        };
        Ok(Self { deny: flat(doc.deny), allow: flat(doc.allow) })
    }

    /// Why `name` is allowed by name (None: no allow entry names it).
    pub fn allowed(&self, name: &str) -> Option<&str> {
        self.allow.iter().find(|(p, _)| matches(p, name)).map(|(_, r)| r.as_str())
    }

    /// Why `name` is denied (None: it isn't, or an allow entry wins).
    pub fn denied(&self, name: &str) -> Option<&str> {
        if self.allowed(name).is_some() {
            return None;
        }
        self.deny.iter().find(|(p, _)| matches(p, name)).map(|(_, r)| r.as_str())
    }
}

/// A map's judgment at a count (`MapPool::judge`).
#[derive(Clone, Debug, PartialEq)]
pub enum Judged {
    /// In the draw at `weight`.
    In { weight: f64, wander_s: f32, small: bool },
    /// No measurements: in at the settings' `unknown_weight`.
    Unknown { weight: f64 },
    /// Out, and why.
    Out(String),
}

impl Judged {
    pub fn weight(&self) -> f64 {
        match self {
            Judged::In { weight, .. } | Judged::Unknown { weight } => *weight,
            Judged::Out(_) => 0.0,
        }
    }
}

#[derive(Clone, Debug, Default)]
struct GamePool {
    game: String,
    fitness: BTreeMap<String, Fitness>,
    rules: Option<PoolRules>,
}

/// Every game's measurements and pool rules (`MapPoolAppExt`), and the
/// maps without measurements already said in the log.
#[derive(Resource, Clone, Debug, Default)]
pub struct MapPool {
    games: Vec<GamePool>,
    told: Vec<String>,
}

/// `game:map` split (no game: `""`), the map's name lower case.
fn split(map: &str) -> (&str, String) {
    match map.split_once(':') {
        Some((g, m)) => (g, m.to_ascii_lowercase()),
        None => ("", map.to_ascii_lowercase()),
    }
}

impl MapPool {
    fn game_mut(&mut self, game: &str) -> &mut GamePool {
        if let Some(i) = self.games.iter().position(|g| g.game.eq_ignore_ascii_case(game)) {
            return &mut self.games[i];
        }
        self.games.push(GamePool { game: game.to_string(), ..Default::default() });
        self.games.last_mut().unwrap()
    }

    fn game(&self, game: &str) -> Option<&GamePool> {
        self.games.iter().find(|g| g.game.eq_ignore_ascii_case(game))
    }

    /// `game`'s measurements added (a map again: replaced).
    pub fn add_fitness(&mut self, game: &str, maps: BTreeMap<String, Fitness>) {
        self.game_mut(game).fitness.extend(maps);
    }

    /// `game`'s rules added to what it has.
    pub fn add_rules(&mut self, game: &str, rules: PoolRules) {
        let g = self.game_mut(game);
        let have = g.rules.get_or_insert_with(PoolRules::default);
        have.deny.extend(rules.deny);
        have.allow.extend(rules.allow);
    }

    /// Whether `game` has pool rules: its installed maps join an
    /// automatic pool (`auto::report`).
    pub fn has_rules(&self, game: &str) -> bool {
        self.game(game).is_some_and(|g| g.rules.is_some())
    }

    /// Whether `game` has any measurements.
    pub fn has_fitness(&self, game: &str) -> bool {
        self.game(game).is_some_and(|g| !g.fitness.is_empty())
    }

    /// Map `map`'s (`game:name`) measurements.
    pub fn fitness(&self, map: &str) -> Option<&Fitness> {
        let (game, name) = split(map);
        self.game(game)?.fitness.get(&name)
    }

    fn rules(&self, game: &str) -> Option<&PoolRules> {
        self.game(game)?.rules.as_ref()
    }

    /// Whether `game`'s map `name` may be in its pool by its rules (Err:
    /// why not).
    pub fn listed(&self, game: &str, name: &str) -> Result<(), String> {
        match self.rules(game).and_then(|r| r.denied(name)) {
            Some(why) => Err(why.to_string()),
            None => Ok(()),
        }
    }

    /// Map `map` (`game:name`) with `players` present, by `s`.
    pub fn judge(&self, map: &str, players: usize, s: &FitSettings) -> Judged {
        let (game, name) = split(map);
        if let Err(why) = self.listed(game, &name) {
            return Judged::Out(why);
        }
        let Some(f) = self.fitness(map) else {
            return Judged::Unknown { weight: s.unknown_weight as f64 };
        };
        if let Some(why) = f.broken() {
            return Judged::Out(why);
        }
        let allowed = self.rules(game).and_then(|r| r.allowed(&name)).is_some();
        if !allowed && let Some(why) = f.look(s) {
            return Judged::Out(why);
        }
        let (wander_s, small) = (f.wander(players, s), f.small(s));
        if !small && wander_s > s.target_s {
            return Judged::Out(format!("{wander_s:.1} s to meet at {players} players, over {} s", s.target_s));
        }
        let scale = if small { s.small_scale } else { 1.0 };
        Judged::In { weight: (s.curve(wander_s) * scale) as f64, wander_s, small }
    }

    /// Each map of `pool`'s weight with `players` present (0: out).
    pub fn weights(&self, pool: &[String], players: usize, s: &FitSettings) -> Vec<f64> {
        pool.iter().map(|m| self.judge(m, players, s).weight()).collect()
    }

    /// `pool` at `players`, a line per map (in: its weight and share of
    /// the draw; out: why), for the console (`map_pool`).
    pub fn lines(&self, pool: &[String], players: usize, s: &FitSettings) -> String {
        let judged: Vec<Judged> = pool.iter().map(|m| self.judge(m, players, s)).collect();
        let total: f64 = judged.iter().map(Judged::weight).sum();
        let ins = judged.iter().filter(|j| j.weight() > 0.0).count();
        let mut out = format!("map pool at {players} players: {ins} of {} maps in", pool.len());
        let mut order: Vec<usize> = (0..pool.len()).collect();
        order.sort_by(|a, b| judged[*b].weight().total_cmp(&judged[*a].weight()).then(a.cmp(b)));
        for i in order {
            let share = |w: f64| if total > 0.0 { w / total * 100.0 } else { 0.0 };
            out.push_str(&match &judged[i] {
                Judged::In { weight, wander_s, small } => format!(
                    "\n  {} {:.1}% (weight {weight:.2}, {wander_s:.1} s to meet{})",
                    pool[i],
                    share(*weight),
                    if *small { ", small" } else { "" }
                ),
                Judged::Unknown { weight } => format!("\n  {} {:.1}% (no measurements)", pool[i], share(*weight)),
                Judged::Out(why) => format!("\n  {} out: {why}", pool[i]),
            });
        }
        out
    }
}

/// The characters present: humans and bots (not NPCs), whether they play
/// yet or not.
pub fn present(world: &World) -> usize {
    world
        .try_query_filtered::<(), (With<Intent>, With<Health>, Without<Npc>)>()
        .map_or(0, |mut q| q.iter(world).count())
}

/// `pool` as the next draw likely takes it with the characters present:
/// the maps let in, heaviest first (the asset offer's prefetch order);
/// `def`'s `map_fit` off: `pool` as it is.
pub fn likeliest(world: &World, def: &MinigameDef, pool: &[String]) -> Vec<String> {
    let Ok(Some(settings)) = FitSettings::of(def) else {
        return pool.to_vec();
    };
    let none = MapPool::default();
    let maps = world.get_resource::<MapPool>().unwrap_or(&none);
    let weights = maps.weights(pool, present(world), &settings);
    let mut order: Vec<usize> = (0..pool.len()).filter(|i| weights[*i] > 0.0).collect();
    order.sort_by(|a, b| weights[*b].total_cmp(&weights[*a]).then(a.cmp(b)));
    order.into_iter().map(|i| pool[i].clone()).collect()
}

/// The weights `def`'s rotation draws `pool` by now (`MapPool::weights`
/// for the characters `present`), None when its `map_fit` is off; each
/// map without measurements said once in the log, and the count in the
/// log.
pub fn draw_weights(world: &mut World, def: &MinigameDef, pool: &[String]) -> Option<Vec<f64>> {
    let settings = match FitSettings::of(def) {
        Ok(s) => s?,
        Err(e) => {
            warn!("{}: map_fit: {e}", def.id);
            return None;
        }
    };
    let players = present(world);
    let mut maps = world.remove_resource::<MapPool>().unwrap_or_default();
    let weights = maps.weights(pool, players, &settings);
    for m in pool {
        if maps.fitness(m).is_none() && maps.listed(split(m).0, &split(m).1).is_ok() && !maps.told.contains(m) {
            info!("map pool: no measurements for {m} (newly installed?): in at weight {}", settings.unknown_weight);
            maps.told.push(m.clone());
        }
    }
    let ins = weights.iter().filter(|w| **w > 0.0).count();
    info!("{}: map pool at {players} players: {ins} of {} maps in", def.id, pool.len());
    world.insert_resource(maps);
    Some(weights)
}

pub trait MapPoolAppExt {
    /// `game`'s measurements (`parse_fitness`; `name` for the error,
    /// which panics: shipped data).
    fn add_map_fitness(&mut self, game: &str, name: &str, text: &str) -> &mut Self;
    /// `game`'s pool rules (`PoolRules::parse`; panics likewise).
    fn add_map_pool_rules(&mut self, game: &str, name: &str, text: &str) -> &mut Self;
}

impl MapPoolAppExt for App {
    fn add_map_fitness(&mut self, game: &str, name: &str, text: &str) -> &mut Self {
        let maps = parse_fitness(text).unwrap_or_else(|e| panic!("{name}: {e}"));
        self.world_mut().get_resource_or_init::<MapPool>().add_fitness(game, maps);
        self
    }

    fn add_map_pool_rules(&mut self, game: &str, name: &str, text: &str) -> &mut Self {
        let rules = PoolRules::parse(text).unwrap_or_else(|e| panic!("{name}: {e}"));
        self.world_mut().get_resource_or_init::<MapPool>().add_rules(game, rules);
        self
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Fixture measurements (made-up maps shaped like the sweep's: a gg_
    /// arena, a middle map, a stock map, a big one, a leak, a broken one).
    pub(crate) const FITNESS: &str = r#"
speed_mps = 6.35
[maps.arena]
area_m2 = 900
sight_m = 8
spawns = 32
spots = 500
[maps.middle]
area_m2 = 2500
sight_m = 8
spawns = 24
spots = 1200
[maps.stock]
area_m2 = 4876
sight_m = 10.5
spawns = 40
spots = 3328
wander_s = { 4 = 9.5, 8 = 4.1, 12 = 2.6 }
[maps.big]
area_m2 = 10000
sight_m = 9
spawns = 32
spots = 7000
[maps.leak]
area_m2 = 30000
sight_m = 20
spawns = 32
spots = 20000
spots_off = 19000
[maps.broken]
loads = false
area_m2 = 0
sight_m = 0
spawns = 16
spots = 0
[maps.bhop_x]
area_m2 = 800
sight_m = 10
spawns = 10
spots = 300
"#;

    pub(crate) const RULES: &str = r#"
[[deny]]
maps = ["bhop_*", "*_cp"]
reason = "a course or mode map"
[[allow]]
maps = ["bhop_fun"]
reason = "a chaos map wanted"
"#;

    fn pool() -> MapPool {
        let mut p = MapPool::default();
        p.add_fitness("g", parse_fitness(FITNESS).unwrap());
        p.add_rules("g", PoolRules::parse(RULES).unwrap());
        p
    }

    fn ids(names: &[&str]) -> Vec<String> {
        names.iter().map(|n| format!("g:{n}")).collect()
    }

    #[test]
    fn the_settings_come_from_the_data_tuned_by_the_definition() {
        let s = FitSettings::shipped();
        assert_eq!((s.target_s, s.small_m2, s.chaos_s), (10.0, 1500.0, 3.0));
        assert_eq!(s.curve(-1.0), 0.2);
        assert_eq!(s.curve(6.0), 1.0);
        assert!((s.curve(3.0) - 0.65).abs() < 1e-5);
        assert_eq!(s.curve(30.0), 0.5);
        let t: toml::Table = toml::from_str("target_s = 8").unwrap();
        assert_eq!(FitSettings::with(&t).unwrap().target_s, 8.0);
        let bad: toml::Table = toml::from_str("weights = [[4, 1.0], [2, 1.0]]").unwrap();
        assert!(FitSettings::with(&bad).is_err());
        let typo: toml::Table = toml::from_str("target = 8").unwrap();
        assert!(FitSettings::with(&typo).is_err(), "unknown keys are errors");
    }

    #[test]
    fn names_match_with_stars_anywhere() {
        assert!(matches("bhop_*", "BHOP_Myztek") && matches("*_cp", "deathroom_cp") && matches("boss*", "bossrush"));
        assert!(matches("*defence", "towerdefence") && matches("a*b*c", "axxbyyc") && matches("training", "Training"));
        assert!(!matches("*_cp", "sandhog_cp1") && !matches("boss*", "theboss") && !matches("a*b*c", "acb"));
        assert!(!matches("training", "training2"));
    }

    #[test]
    fn the_pool_follows_the_count() {
        let p = pool();
        let s = FitSettings::shipped();
        let all = ids(&["arena", "middle", "stock", "big"]);
        let in_at = |n: usize| -> Vec<String> {
            all.iter().zip(p.weights(&all, n, &s)).filter(|(_, w)| *w > 0.0).map(|(m, _)| m.clone()).collect()
        };
        // stock: 9.6 s at 4 (in), big: about 23 s at 4, 9.8 at 8.
        assert_eq!(in_at(4), ids(&["arena", "middle", "stock"]));
        assert_eq!(in_at(8), all);
        assert_eq!(in_at(12), all);
        assert!(matches!(p.judge("g:big", 4, &s), Judged::Out(ref w) if w.contains("over 10 s")), "{:?}", p.judge("g:big", 4, &s));
        // The small arena is in at any count, at a fraction of the curve.
        for n in [2, 4, 8, 12, 32] {
            let Judged::In { weight, small, .. } = p.judge("g:arena", n, &s) else { panic!() };
            assert!(small && weight > 0.0 && weight <= 0.25 + 1e-9, "{n}: {weight}");
        }
        // Best fit 4-8 s: the stock map at 8 (4.1 s) outweighs it at 12 (2.6 s).
        assert!(p.judge("g:stock", 8, &s).weight() > p.judge("g:stock", 12, &s).weight());
        assert_eq!(p.judge("g:stock", 8, &s).weight(), 1.0);
        // The count's own measure: the sweep's figures again.
        let f = p.fitness("g:STOCK").unwrap();
        for (n, w) in [(4, 9.5), (8, 4.1), (12, 2.6)] {
            assert!((f.wander(n, &s) - w).abs() < 0.1, "{n}: {}", f.wander(n, &s));
        }
    }

    #[test]
    fn the_rules_and_the_flags_keep_maps_out_and_allow_wins() {
        let mut p = pool();
        let s = FitSettings::shipped();
        assert!(matches!(p.judge("g:bhop_x", 8, &s), Judged::Out(ref w) if w == "a course or mode map"));
        assert!(matches!(p.judge("g:leak", 32, &s), Judged::Out(ref w) if w.contains("area 30000")));
        assert!(matches!(p.judge("g:broken", 8, &s), Judged::Out(_)));
        assert_eq!(p.listed("g", "town_cp"), Err("a course or mode map".into()));
        assert_eq!(p.listed("g", "bhop_fun"), Ok(()), "allowed by name");
        assert_eq!(p.listed("other", "bhop_x"), Ok(()), "another game's rules don't apply");
        // Allowed: the flags can't keep it out (the count still can).
        p.add_rules("g", PoolRules::parse("[[allow]]\nmaps = [\"leak\"]\nreason = \"looked at\"").unwrap());
        assert!(p.judge("g:leak", 32, &s).weight() > 0.0, "{:?}", p.judge("g:leak", 32, &s));
        assert!(matches!(p.judge("g:broken", 8, &s), Judged::Out(_)), "a broken map stays out");
    }

    #[test]
    fn a_map_without_measurements_is_in_at_mid_weight() {
        let p = pool();
        let s = FitSettings::shipped();
        assert_eq!(p.judge("g:new_map", 4, &s), Judged::Unknown { weight: 0.5 });
        assert_eq!(p.judge("nobody:map", 12, &s).weight(), 0.5);
        assert!(p.lines(&ids(&["new_map", "big"]), 4, &s).contains("g:new_map 100.0% (no measurements)"));
    }

    #[test]
    fn map_fit_is_on_with_a_random_rotation_unless_turned_off() {
        let def = |extra: &str| {
            MinigameDef::parse(
                "t",
                &format!(
                    "id = \"t:t\"\nname = \"T\"\nplayers = {{ min = 1, max = 4 }}\nmaps = [\"g:a\"]\n\
                     teams = \"free_for_all\"\ntime_limit = 60\n{extra}\n[rules]\nmodule = \"chimera:ladder\"\nladder = [\"x:y\"]\n"
                ),
            )
            .unwrap()
        };
        assert!(FitSettings::of(&def("")).unwrap().is_none(), "in turn: off");
        assert!(FitSettings::of(&def("rotation = \"random\"")).unwrap().is_some());
        assert!(FitSettings::of(&def("rotation = \"random\"\nmap_fit = false")).unwrap().is_none());
        assert_eq!(FitSettings::of(&def("map_fit = { target_s = 7 }")).unwrap().unwrap().target_s, 7.0);
        let bad = MinigameDef::parse("t", &format!("{}", "id = \"t:t\"\nname = \"T\"\nplayers = { min = 1, max = 4 }\nmaps = [\"g:a\"]\nteams = \"free_for_all\"\ntime_limit = 60\nmap_fit = { target = 7 }\n[rules]\nmodule = \"chimera:ladder\"\nladder = [\"x:y\"]\n"));
        assert!(bad.is_err(), "checked when read");
    }
}
